import pandas as pd
import matplotlib.pyplot as plt

# 1. Load the simulation data generated by your C++ engine
try:
    data = pd.read_csv("junction_mesh.csv")
except FileNotFoundError:
    print("[ERROR] Could not find junction_mesh.csv. Run your C++ code first!")
    exit()

# 2. Initialize the plot layout
plt.figure(figsize=(10, 5))

# Plot the top aluminum-oxide interface layer (Al / Al2O3)
plt.plot(data['X'], data['Z_Top'], color='#d32f2f', label='Top Interface (Al / Al₂O₃)', linewidth=2)

# Plot the bottom aluminum-oxide interface layer (Al2O3 / Al)
plt.plot(data['X'], data['Z_Bottom'], color='#1976d2', label='Bottom Interface (Al₂O₃ / Al)', linewidth=2)

# Shade the Al2O3 tunnel barrier region to show roughness variations cleanly
plt.fill_between(data['X'], data['Z_Bottom'], data['Z_Top'], color='#ffeb3b', alpha=0.3, label='Al₂O₃ Tunnel Oxide')

# 3. Add academic styling parameters matching Glasgow presentation standards
plt.title("Simulated Al/Al₂O₃/Al Josephson Junction Barrier Profile", fontsize=14, fontweight='bold', pad=15)
plt.xlabel("Junction Lateral Position (nm)", fontsize=12)
plt.ylabel("Barrier Vertical Profile Height (nm)", fontsize=12)
plt.grid(True, linestyle='--', alpha=0.5)
plt.legend(loc='upper right', frameon=True, shadow=True)

# Tighten layout and save a PNG copy automatically for your repository
plt.tight_layout()
plt.savefig("josephson_junction_roughness.png", dpi=300)
print("[SUCCESS] Saved a high-res plot as 'josephson_junction_roughness.png'!")

# Display the window live
plt.show()
